import React, { useState } from "react";
import TopicSelector from "./Components/TopicSelector";
import DebateArena from "./components/DebateArena";
import "./App.css";

function App() {
  const [topic, setTopic] = useState("");
  const [debateStarted, setDebateStarted] = useState(false);

  const handleStartDebate = (selectedTopic) => {
    setTopic(selectedTopic);
    setDebateStarted(true);
  };

  const handleReset = () => {
    setTopic("");
    setDebateStarted(false);
  };

  return (
    <div className="app">
      <div className="bg-grid" />
      <header className="header">
        <div className="logo">
          <div className="logo-icon">⚔️</div>
          <span>AI <span className="accent">Debate</span> Partner</span>
        </div>
        <div className="status-pill">
          <div className="dot" />
          Claude AI is ready to fight
        </div>
      </header>
      <main className="main">
        {!debateStarted ? (
          <TopicSelector onStart={handleStartDebate} />
        ) : (
          <DebateArena topic={topic} onReset={handleReset} />
        )}
      </main>
    </div>
  );
}

export default App;
